examples.code:
// 获取所有目标
const allGoals = await Aboutme.plugins.tracker.getGoals({});
setResult(allGoals);

// 获取进行中的目标
const activeGoals = await Aboutme.plugins.tracker.getGoals({ status: 'active' });
setResult(activeGoals);

// 获取'学习'分组的目标
const studyGoals = await Aboutme.plugins.tracker.getGoals({ group: '学习' });
setResult(studyGoals);

// 获取'健康'分组中已完成的目标
const completedHealthGoals = await Aboutme.plugins.tracker.getGoals({ status: 'completed', group: '健康' });
setResult(completedHealthGoals);

// 分页获取目标（前20个）
const result = await Aboutme.plugins.tracker.getGoals({ offset: 0, count: 20 });
setResult(`共 ${result.total} 个目标，当前返回 ${result.data.length} 个`);

// 分页获取学习分组的目标
const result = await Aboutme.plugins.tracker.getGoals({ group: '学习', offset: 0, count: 10 });
setResult(`学习分组共 ${result.total} 个目标，当前显示 ${result.data.length} 个，还有更多: ${result.hasMore}`);

const goal = await Aboutme.plugins.tracker.getGoal({ goalId: 'goal123' });
const result = `目标名称: ${goal.name}, 进度: ${goal.currentValue}/${goal.targetValue}`;
setResult(result);

// 创建每日阅读目标(自动生成ID)
const goal = await Aboutme.plugins.tracker.createGoal({
  name: '每日阅读',
  unitType: '分钟',
  targetValue: 30,
  group: '学习'
});
setResult(goal);

// 创建每周运动目标(自定义ID)
const weeklyGoal = await Aboutme.plugins.tracker.createGoal({
  id: 'goal123',
  name: '每周运动',
  unitType: '小时',
  targetValue: 5,
  group: '健康',
  dateType: 'weekly'
});
setResult(weeklyGoal);

// 更新目标名称和目标值
const updated = await Aboutme.plugins.tracker.updateGoal({
  goalId: 'goal123',
  updateJson: {
    name: '每日深度阅读',
    targetValue: 60
  }
});
setResult(updated);

// 更新提醒时间和分组
const updated2 = await Aboutme.plugins.tracker.updateGoal({
  goalId: 'goal123',
  updateJson: {
    reminderTime: '20:00',
    group: '个人成长'
  }
});
setResult(updated2);

const result = await Aboutme.plugins.tracker.deleteGoal({ goalId: 'goal123' });
if (result.success) {
  setResult(`成功删除目标: ${result.goalId}`);
} else {
  setResult(`删除失败: ${result.error}`);
}

// 添加今日阅读记录(自动生成ID)
const record = await Aboutme.plugins.tracker.recordData({
  goalId: 'goal123',
  value: 30,
  note: '阅读《代码整洁之道》'
});
setResult(record);

// 添加昨日的记录
const yesterday = await Aboutme.system.getCustomDate({subtract: {days: 1}, relativePosition: 'startOfDay', format: 'iso'});
const pastTime = yesterday.replace(/T.*/, 'T20:00:00.000Z');
const pastRecord = await Aboutme.plugins.tracker.recordData({
  goalId: 'goal123',
  value: 45,
  note: '昨日补记',
  dateTime: pastTime
});
setResult(pastRecord);

// 使用自定义ID添加记录
const customRecord = await Aboutme.plugins.tracker.recordData({
  id: 'record123',
  goalId: 'goal123',
  value: 25,
  note: '晨读'
});
setResult(customRecord);

// 获取所有记录
const allRecords = await Aboutme.plugins.tracker.getRecords({ goalId: 'goal123' });
setResult(allRecords);

// 获取最近 10 条记录（使用 limit）
const recentRecords = await Aboutme.plugins.tracker.getRecords({ goalId: 'goal123', limit: 10 });
const result = recentRecords.map(record => `${record.recordedAt}: ${record.value} ${record.note || ''}`).join('\n');
setResult(result);

// 分页获取记录（前20条）
const result = await Aboutme.plugins.tracker.getRecords({ goalId: 'goal123', offset: 0, count: 20 });
setResult(`共 ${result.total} 条记录，当前返回 ${result.data.length} 条`);

// 分页获取记录（第二页）
const result = await Aboutme.plugins.tracker.getRecords({ goalId: 'goal123', offset: 20, count: 20 });
setResult(`还有更多记录: ${result.hasMore}，当前返回 ${result.count} 条`);

const result = await Aboutme.plugins.tracker.deleteRecord({ recordId: 'record123' });
if (result.success) {
  setResult(`成功删除记录: ${result.recordId}`);
} else {
  setResult(`删除失败: ${result.error}`);
}

const progress = await Aboutme.plugins.tracker.getProgress({ goalId: 'goal123' });
const result = `进度: ${progress.percentage}%\n完成状态: ${progress.isCompleted ? '已完成' : '进行中'}`;
setResult(result);

// 获取全局统计
const stats = await Aboutme.plugins.tracker.getStats({});
const result = `总目标数: ${stats.totalGoals}
今日完成: ${stats.todayCompleted}
本月完成: ${stats.monthCompleted}
整体进度: ${(stats.overallProgress * 100).toFixed(1)}%
分组列表: ${stats.groups.join(', ')}`;
setResult(result);

// 获取单个目标统计
const goalStats = await Aboutme.plugins.tracker.getStats({ goalId: 'goal123' });
const result = `目标名称: ${goalStats.goalName}\n总记录数: ${goalStats.totalRecords}\n累计值: ${goalStats.totalValue}`;
setResult(result);
